// ❌ Lưu password dạng plain text
await db.save({ username, password })  // thảm họa khi DB bị leak

// ❌ Dùng MD5 — crack được bằng rainbow table trong vài giây
const hash = md5(password)

// ✅ bcrypt với cost factor đủ cao
const hash = await bcrypt.hash(password, 12)

// ❌ Hardcode secret trong code
const JWT_SECRET = 'mysecret123'  // bị lộ khi push lên GitHub!

// ✅ Đọc từ environment variable
const JWT_SECRET = process.env.JWT_SECRET

// ❌ Insecure Design: flow reset password đoán được
// Câu hỏi bảo mật 'Tên thú cưng đầu tiên?' — dễ đoán từ social media
if (answers.petName === user.petName) allowPasswordReset()

// ✅ Secure Design: gửi token ngẫu nhiên qua email đã verify
const token = crypto.randomBytes(32).toString('hex')
await db.saveResetToken(userId, token, expiresAt: Date.now() + 3600000)
await sendEmail(user.email, `Reset link: /reset?token=${token}`)
// Token chỉ dùng một lần, hết hạn sau 1 giờ

