// ❌ Không log gì — xảy ra tấn công cũng không biết
app.post('/login', async (req, res) => {
  const user = await authenticate(req.body)
  if (!user) return res.status(401).json({ error: 'Invalid credentials' })
  // ...
})

// ✅ Log có cấu trúc — dễ search và alert
app.post('/login', async (req, res) => {
  const user = await authenticate(req.body)
  if (!user) {
    logger.warn({
      event: 'LOGIN_FAILURE',
      username: req.body.username,
      ip: req.ip,
      userAgent: req.headers['user-agent'],
      timestamp: new Date().toISOString()
    })
    // Alert nếu >5 failures trong 60 giây từ cùng IP
    await checkAndAlert('login_failure', req.ip)
    return res.status(401).json({ error: 'Invalid credentials' })
  }
  logger.info({ event: 'LOGIN_SUCCESS', userId: user.id, ip: req.ip })
})

