// Tính năng: tạo screenshot từ URL
app.post('/screenshot', async (req, res) => {
  const { url } = req.body  // ❌ không validate!
  const screenshot = await puppeteer.screenshot(url)
  // Attacker nhập: http://169.254.169.254/latest/meta-data/iam/credentials
  // → Server gọi đến metadata service và trả về AWS credentials!
  res.json({ screenshot })
})

// ✅ Validate URL trước khi fetch
async function validateUrl(url) {
  const parsed = new URL(url)
  // Chỉ cho phép HTTPS và domain public
  if (parsed.protocol !== 'https:') throw new Error('Only HTTPS allowed')
  // Resolve DNS và kiểm tra không phải IP private
  const ip = await dns.resolve4(parsed.hostname)
  if (isPrivateIP(ip[0])) throw new Error('Private IP not allowed')
  return url
}

